        "operation": operation_id,
        "law": "command-idempotence-from-state",
        "guards": guards,
        "cases": [
            {
                "id": "a_repeat_is_a_no_op_or_a_typed_conflict",
                "given": "the same request sent again after the first call succeeded",
                "expect": {
