fn physical_select_relations(
    tokens: &[Token],
    depths: &[usize],
    select: usize,
    end: usize,
    depth: usize,
    relations: &BTreeMap<String, BTreeSet<String>>,
) -> BTreeSet<String> {
    let mut physical = BTreeSet::new();
    for index in select + 1..end.saturating_sub(1) {
