) -> Result<(), GenerateError> {
    use AccessOperationErrorLiteral as Code;

    let expected = operation_constraints(table, action, operation)
        .into_iter()
        .map(|constraint| constraint_error_code(constraint.kind()))
        .collect::<BTreeSet<_>>();
    let declared = operation
        .error_details
