//! The wire scalars every operation parses, spelled once.
//!
//! Parse and RE-SPELL, not merely validate. The canonicalization contract fixes
//! uuids as lowercase-hyphenated and timestamps as UTC RFC 3339 with six
//! fractional digits, so a caller's spelling must reach the database -- and the
//! command bytes -- in one form, or two deliveries of the same command would
//! canonicalize differently and the idempotency key would stop working.

use wamn_postgres_statements::{TimestampTz, Uuid};

use crate::error::{AccessError, AccessErrorKind};

/// The three states an appointment can hold, in the order it moves through.
pub(crate) const STATUSES: [&str; 3] = ["scheduled", "arrived", "departed"];

pub(crate) fn uuid(field: &str, value: &str) -> Result<Uuid, AccessError> {
    value
        .parse::<uuid::Uuid>()
        .map(|parsed| Uuid(parsed.hyphenated().to_string()))
        .map_err(|_| AccessError::field(AccessErrorKind::InvalidInput, field))
}

pub(crate) fn timestamp(field: &str, value: &str) -> Result<Moment, AccessError> {
    chrono::DateTime::parse_from_rfc3339(value)
        .map(|parsed| Moment(parsed.to_utc()))
        .map_err(|_| AccessError::field(AccessErrorKind::InvalidInput, field))
}

/// A calendar day, as the two UTC instants that bound it.
///
/// The day is bounded HERE and not in SQL. A `date` cast in the statement would
/// read the session time zone, and this scenario's slots are UTC.
pub(crate) fn day(field: &str, value: &str) -> Result<(Moment, Moment), AccessError> {
    let parsed = chrono::NaiveDate::parse_from_str(value, "%Y-%m-%d")
        .map_err(|_| AccessError::field(AccessErrorKind::InvalidInput, field))?;
    let next = parsed
        .succ_opt()
        .ok_or_else(|| AccessError::field(AccessErrorKind::InvalidInput, field))?;
    Ok((midnight(parsed), midnight(next)))
}

fn midnight(date: chrono::NaiveDate) -> Moment {
    Moment(date.and_hms_opt(0, 0, 0).expect("midnight is a valid time").and_utc())
}

pub(crate) fn status(field: &str, value: &str) -> Result<String, AccessError> {
    if STATUSES.contains(&value) {
        Ok(value.to_owned())
    } else {
        Err(AccessError::field(AccessErrorKind::InvalidInput, field))
    }
}

/// One instant, ordered as a time and spelled as the frozen wire form.
#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub(crate) struct Moment(pub(crate) chrono::DateTime<chrono::Utc>);

impl Moment {
    /// The one spelling that reaches the database and the command bytes.
    pub(crate) fn text(&self) -> String {
        self.0.format("%Y-%m-%dT%H:%M:%S%.6fZ").to_string()
    }

    pub(crate) fn bind(&self) -> TimestampTz {
        TimestampTz(self.text())
    }
}

