        command.idempotency_key.clone(),
        canonical.to_vec(),
    )
    .await
    .map_err(|e| error::from_statement(&e))?
    .ok_or_else(AccessError::retry)?;

    dock_create::insert_dock(transaction, claim.dock_id.clone(), command.name.clone())
        .await
        .map_err(|e| error::from_statement(&e))?;

    dock_create::finalize_command(
        transaction,
        command.idempotency_key.clone(),
        canonical.to_vec(),
        claim.dock_id.clone(),
    )
    .await
    .map_err(|e| error::from_statement(&e))?
    .ok_or_else(AccessError::retry)?;

