//! `appointment.query` -- one dock's day, filtered by status and slot-ordered.
//!
//! The statement orders by `slot_start`, so the answer arrives in slot order
//! and this module never sorts. The day is bounded in Rust rather than by a
//! `date` cast in SQL, because a cast would read the session time zone.

use serde::Deserialize;
use wamn_postgres_statements::Connection;

use crate::error::{self, AccessError, AccessErrorKind};
use crate::generated::wamn::appointment_query as sql;
use crate::scalar;

pub(crate) const REFUSALS: &[AccessErrorKind] = &[
    AccessErrorKind::InvalidInput,
    AccessErrorKind::Retry,
    AccessErrorKind::Timeout,
    AccessErrorKind::PermissionDenied,
    AccessErrorKind::InternalError,
];

/// One envelope item's read body: the item itself, less its correlation id.
#[derive(Debug, Deserialize)]
pub(crate) struct QueryInput {
    pub(crate) dock_id: String,
    pub(crate) day: String,
    pub(crate) status: String,
}

/// Read one dock's appointments for one day.
///
/// # Errors
///
/// [`AccessError`] carrying the literal and detail the operation contract
/// declares for that refusal.
pub(crate) async fn execute(
    connection: &mut Connection,
    input: &QueryInput,
) -> Result<serde_json::Value, AccessError> {
    let dock_id = scalar::uuid("dock_id", &input.dock_id)?;
    let (day_start, day_end) = scalar::day("day", &input.day)?;
    let status = scalar::status("status", &input.status)?;

    let mut transaction = connection.begin().await.map_err(|e| error::from_statement(&e))?;
    let rows = sql::query_appointment(
        &mut transaction,
        dock_id,
        day_start.bind(),
        day_end.bind(),
        status,
    )
    .await;
    match rows {
        Ok(rows) => {
            transaction.commit().await.map_err(|e| error::from_statement(&e))?;
            Ok(page(&rows))
        }
        Err(failure) => {
            let _ = transaction.rollback().await;
            Err(error::from_statement(&failure))
        }
    }
}

fn page(rows: &[sql::QueryAppointmentRow]) -> serde_json::Value {
    serde_json::json!({
        "appointments": rows
            .iter()
            .map(|row| serde_json::json!({
                "appointment_id": row.id.0,
                "carrier_id": row.carrier_id.0,
                "dock_id": row.dock_id.0,
                "slot_start": row.slot_start.0,
                "slot_end": row.slot_end.0,
                "status": row.status,
                "arrived_at": row.arrived_at.as_ref().map(|at| at.0.clone()),
            }))
            .collect::<Vec<_>>(),
    })
}
