import pathlib
p = pathlib.Path("components/application/dock/src/scalar.rs")
s = p.read_text()
old = """pub(crate) fn day(field: &str, value: &str) -> Result<(Moment, Moment), AccessError> {
    let parsed = chrono::NaiveDate::parse_from_str(value, "%Y-%m-%d")
        .map_err(|_| AccessError::field(AccessErrorKind::InvalidInput, field))?;
"""
new = """pub(crate) fn day(field: &str, value: &str) -> Result<(Moment, Moment), AccessError> {
    // chrono accepts `2026-1-1` for `%Y-%m-%d`, and the contract spells a date
    // one way only, so the shape is checked before the calendar is.
    let shaped = value.len() == "2026-10-01".len()
        && value.bytes().enumerate().all(|(index, byte)| match index {
            4 | 7 => byte == b'-',
            _ => byte.is_ascii_digit(),
        });
    let parsed = chrono::NaiveDate::parse_from_str(value, "%Y-%m-%d")
        .ok()
        .filter(|_| shaped)
        .ok_or_else(|| AccessError::field(AccessErrorKind::InvalidInput, field))?;
"""
assert old in s
s = s.replace(old, new, 1)
p.write_text(s)
print("ok")
PY
